CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('owner','manager')));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_own_role ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.kuku_role() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT role FROM public.user_roles WHERE user_id=auth.uid() $$;
REVOKE ALL ON FUNCTION public.kuku_role() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.kuku_role() TO authenticated;
CREATE TABLE public.record_store (owner_id uuid NOT NULL, table_name text NOT NULL, id text NOT NULL, data jsonb NOT NULL DEFAULT '{}', deleted_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), server_updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(owner_id,table_name,id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.record_store TO authenticated; GRANT ALL ON public.record_store TO service_role;
ALTER TABLE public.record_store ENABLE ROW LEVEL SECURITY;
CREATE POLICY records_read ON public.record_store FOR SELECT TO authenticated USING(owner_id=auth.uid() AND public.kuku_role() IS NOT NULL);
CREATE POLICY records_insert ON public.record_store FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid() AND (public.kuku_role()='owner' OR (public.kuku_role()='manager' AND table_name NOT IN ('customers','cashLogs','documents','auditLog','user_roles'))));
CREATE POLICY records_update ON public.record_store FOR UPDATE TO authenticated USING(owner_id=auth.uid() AND (public.kuku_role()='owner' OR (public.kuku_role()='manager' AND table_name NOT IN ('sales','salePayments','expenses','expensePayments','customers','cashLogs','documents','auditLog')))) WITH CHECK(owner_id=auth.uid());
CREATE POLICY records_delete ON public.record_store FOR DELETE TO authenticated USING(owner_id=auth.uid() AND public.kuku_role()='owner');
CREATE INDEX record_changes ON public.record_store(owner_id,server_updated_at);
CREATE TABLE public.user_preferences (user_id uuid PRIMARY KEY, data jsonb NOT NULL DEFAULT '{}');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.user_preferences TO authenticated; GRANT ALL ON public.user_preferences TO service_role;
ALTER TABLE public.user_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_preferences ON public.user_preferences FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.legacy_user_mapping (original_user_id text PRIMARY KEY, auth_user_id uuid NOT NULL UNIQUE, verified_email text NOT NULL UNIQUE);
GRANT ALL ON public.legacy_user_mapping TO service_role; ALTER TABLE public.legacy_user_mapping ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.kuku_record_timestamp() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.server_updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER record_timestamp BEFORE INSERT OR UPDATE ON public.record_store FOR EACH ROW EXECUTE FUNCTION public.kuku_record_timestamp();
CREATE FUNCTION public.kuku_new_account() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'owner'); RETURN NEW; END $$;
CREATE TRIGGER kuku_account_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.kuku_new_account();